} else if (pppoeUser2 && pppoeUser2.value && pppoeUser2.value[0] && pppoeUser2.value[0].trim() !== "" && pppoeUser2.value[0].trim() !== " ") {
    declare("VirtualParameters.pppoeUsername", {path: hourly}, {value: pppoeUser2.value[0]});
}

// --- pppoeUsername2 (backup) ---
if (pppoeUser2 && pppoeUser2.value && pppoeUser2.value[0] && pppoeUser2.value[0].trim() !== "" && pppoeUser2.value[0].trim() !== " ") {
    declare("VirtualParameters.pppoeUsername2", {path: hourly}, {value: pppoeUser2.value[0]});
