    declare("VirtualParameters.getdeviceuptime", {path: hourly}, {value: String(deviceUptime.value[0])});
}

// --- RXPower — formula from alijayanet reference: 30 + log10(raw * 10^-7) * 10 ---
let rxValue = "N/A";
if (eponRx && eponRx.value && eponRx.value[0] !== undefined) {
    const raw = Number(eponRx.value[0]);
    if (!isNaN(raw) && raw > 0) {
        const db = 30 + (Math.log10(raw * Math.pow(10, -7)) * 10);
        rxValue = String(Math.ceil(db * 100) / 100) + " dBm";
    }
} else if (gponRx && gponRx.value && gponRx.value[0] !== undefined) {
    const raw = Number(gponRx.value[0]);
    if (!isNaN(raw) && raw > 0) {
        const db = 30 + (Math.log10(raw * Math.pow(10, -7)) * 10);
        rxValue = String(Math.ceil(db * 100) / 100) + " dBm";
    }
}
declare("VirtualParameters.RXPower", {path: hourly}, {value: rxValue});

// --- gettemp — formula: if < 150 direct, else linear regression ---
let tempValue = "N/A";
let tempRaw = undefined;
if (eponTemp && eponTemp.value && eponTemp.value[0] !== undefined) {
    tempRaw = Number(eponTemp.value[0]);
} else if (gponTemp && gponTemp.value && gponTemp.value[0] !== undefined) {
    tempRaw = Number(gponTemp.value[0]);
}
if (tempRaw !== undefined && !isNaN(tempRaw)) {
    if (tempRaw < 150) {
        tempValue = String(tempRaw);
    } else {
        // Linear regression from reference VP script
        const tr069Values = [11509, 11876, 10866, 10592, 11142, 11968];
        const temperatures = [45, 46, 42, 41, 43, 46];
        const n = tr069Values.length;
        let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
        for (let i = 0; i < n; i++) {
            sumX += tr069Values[i];
            sumY += temperatures[i];
            sumXY += tr069Values[i] * temperatures[i];
            sumX2 += tr069Values[i] * tr069Values[i];
        }
        const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
        const intercept = (sumY - slope * sumX) / n;
        const temperature = slope * tempRaw + intercept;
        tempValue = String(Math.round(temperature));
    }
}
declare("VirtualParameters.gettemp", {path: hourly}, {value: tempValue});

